<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {api} from '../services/accounting.js';
import {useAccess} from '../composables/access.js';
import {reportMoney as money,reportDate as date} from '../services/report-format.js';
import {cents,decimal} from '../../../shared/money.js';
import {remittanceError} from '../locales/remittances.js';
import {downloadRemittance} from '../services/bank-remittances.js';
import TradeTabs from '../components/TradeTabs.vue';
import PortfolioTabs from '../components/PortfolioTabs.vue';
import FormDialog from '../components/FormDialog.vue';
const {can}=useAccess();
const props=defineProps({direction:{type:String,required:true}});
const direction=computed(()=>props.direction),title=computed(()=>direction.value==='issued'?'Remesas de clientes':'Remesas de proveedores');
const rows=ref([]),history=ref([]),selected=ref([]),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),review=ref(null),cancelling=ref(null),search=ref(''),through=ref('');
const now=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Madrid'}).format(new Date());
const form=ref({requested_date:now,iban:'',bic:'',creditor_id:'',initiator_id:''});
let generation=0,request=crypto.randomUUID(),active=true;
const sameSection=scope=>active&&scope===direction.value;
const visible=computed(()=>rows.value.filter(row=>(!through.value||row.due_date<=through.value)&&(!search.value||[row.name,row.reference,String(row.receipt_id)].some(value=>value.toLocaleLowerCase('es').includes(search.value.toLocaleLowerCase('es'))))));
const total=computed(()=>decimal(rows.value.filter(row=>selected.value.includes(row.receipt_id)).reduce((sum,row)=>sum+cents(row.amount),0n)));
const statuses={prepared:'Preparada',cancelled:'Cancelada en el programa',archived:'Histórica'};
function body(){return {direction:direction.value,receipt_ids:[...selected.value],...form.value};}
async function load(){const ticket=++generation;loading.value=true;error.value='';review.value=null;selected.value=[];
 try{const [options,list]=await Promise.all([api('/bank-remittances/options?direction='+direction.value),api('/bank-remittances?direction='+direction.value)]);if(ticket!==generation)return;rows.value=options.rows;history.value=list;const own=options.company;form.value={...form.value,iban:own.iban||'',bic:own.bic||'',creditor_id:own.sepa_creditor_id||'',initiator_id:own.bank_initiator_id||''};}
 catch(cause){if(ticket===generation)error.value=remittanceError(cause);}finally{if(ticket===generation)loading.value=false;}
}
function selectVisible(){const available=visible.value.filter(row=>!row.issues.length).map(row=>row.receipt_id);selected.value=[...new Set([...selected.value,...available])];}
async function preview(){if(!selected.value.length||busy.value)return;const ticket=generation;busy.value=true;error.value='';try{const sent=body(),result=await api('/bank-remittances/preview',{method:'POST',body:sent});if(ticket!==generation)return;request=crypto.randomUUID();review.value={...result,sent};}catch(cause){if(ticket===generation)error.value=remittanceError(cause);}finally{busy.value=false;}}
async function generate(){if(!review.value?.ready||busy.value)return;const scope=direction.value,ticket=generation;busy.value=true;error.value='';let created;
 try{created=await api('/bank-remittances',{method:'POST',body:{...review.value.sent,preview_hash:review.value.preview_hash,request_id:request}});if(ticket!==generation)return;review.value=null;notice.value='Remesa '+created.id+' preparada. Registra el cobro o pago cuando el banco lo confirme.';await load();if(sameSection(scope))await downloadRemittance(created);}
 catch(cause){if(sameSection(scope))error.value=created?'La remesa está guardada. Descarga el fichero desde el historial.':remittanceError(cause);}finally{busy.value=false;}
}
async function download(row){busy.value=true;error.value='';try{await downloadRemittance(row);}catch(cause){error.value=remittanceError(cause);}finally{busy.value=false;}}
async function cancel(){const ticket=generation;busy.value=true;error.value='';try{await api('/bank-remittances/'+cancelling.value.id+'/cancel',{method:'POST'});if(ticket!==generation)return;cancelling.value=null;notice.value='Remesa cancelada en el programa. Sus recibos vuelven a estar disponibles.';await load();}catch(cause){if(ticket===generation)error.value=remittanceError(cause);}finally{busy.value=false;}}
watch(direction,()=>{rows.value=[];history.value=[];notice.value='';search.value='';through.value='';cancelling.value=null;load();},{immediate:true});onBeforeUnmount(()=>{active=false;generation++;});
</script>
<template>
 <TradeTabs /><PortfolioTabs /><div class="page-heading"><div><h1>{{ title }}</h1><p class="muted">{{ direction==='issued'?'Cobros domiciliados de clientes · 19 SEPA CORE.':'Pagos por transferencia a proveedores · 34 SEPA.' }}</p></div><button class="button" :disabled="busy||loading" @click="load">Actualizar</button></div>
 <p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><p v-if="notice" class="success-note" role="status">{{ notice }}</p>
 <form class="panel remittance-settings" @submit.prevent="preview"><fieldset :disabled="busy||loading"><div class="filters"><label>{{ direction==='issued'?'Cobrar a partir de':'Pagar a partir de' }}<input v-model="form.requested_date" name="remittance_date" type="date" :min="now" max="9999-12-31" required></label><label>IBAN de la empresa<input v-model="form.iban" name="remittance_iban" maxlength="50" required></label><label>BIC / SWIFT (opcional)<input v-model="form.bic" name="remittance_bic" maxlength="11"></label><label v-if="direction==='issued'">Identificador de acreedor SEPA<input v-model="form.creditor_id" name="remittance_creditor" maxlength="35" required></label><label>Identificador del presentador (si lo exige el banco)<input v-model="form.initiator_id" name="remittance_initiator" maxlength="35"></label></div><p class="muted">Los datos habituales del banco se guardan en <RouterLink to="/empresas">la ficha de empresa</RouterLink>. Los IBAN de clientes y proveedores y los mandatos de domiciliación se guardan en <RouterLink to="/cuentas">sus subcuentas</RouterLink>.</p>
 <div class="filters"><label>Buscar recibo, factura o tercero<input v-model="search" type="search"></label><label>Vencimientos hasta<input v-model="through" type="date"></label><button type="button" class="button" @click="selectVisible">Seleccionar disponibles</button><button type="button" class="button" @click="selected=[]">Quitar selección</button></div>
 <p v-if="loading" role="status">Cargando recibos…</p><div v-else class="table-wrap"><table><thead><tr><th>Incluir</th><th>Recibo / factura</th><th>{{ direction==='issued'?'Cliente':'Proveedor' }}</th><th>Vencimiento</th><th>IBAN</th><th class="amount">Pendiente</th><th>Datos a completar</th></tr></thead><tbody><tr v-for="row in visible" :key="row.receipt_id" :data-remittance-receipt="row.receipt_id"><td><input v-model="selected" type="checkbox" :value="row.receipt_id" :disabled="!!row.issues.length" :aria-label="'Incluir recibo '+row.receipt_id"></td><td>{{ row.receipt_id }} · {{ row.reference }}</td><td>{{ row.name }}</td><td>{{ date(row.due_date) }}</td><td class="account-code">{{ row.iban||'—' }}</td><td class="amount">{{ money(row.amount) }}</td><td><p v-for="issue in row.issues" :key="issue" class="remittance-issue">{{ remittanceError({code:issue}) }}</p><RouterLink v-if="row.issues.some(issue=>issue!=='RECEIPT_IN_REMITTANCE')" to="/cuentas">Revisar ficha</RouterLink><span v-if="!row.issues.length" class="badge">Disponible</span></td></tr><tr v-if="!visible.length"><td colspan="7" class="empty-cell">{{ direction==='issued'?'No hay recibos pendientes de clientes con domiciliación bancaria.':'No hay recibos pendientes de proveedores con pago por transferencia.' }}</td></tr></tbody></table></div>
 <div class="actions"><strong>{{ selected.length }} recibos · {{ money(total) }} €</strong><button class="button primary" :disabled="!can('accounting_write')||!selected.length||busy||loading">Revisar remesa</button></div></fieldset></form>
 <section class="panel remittance-history"><h2>{{ direction==='issued'?'Historial de remesas de clientes':'Historial de remesas de proveedores' }}</h2><p class="muted">Generar el fichero conserva los recibos pendientes. La descarga posterior recupera el mismo fichero.</p><div class="table-wrap"><table><thead><tr><th>Remesa</th><th>Tipo</th><th>A partir de</th><th>Recibos</th><th class="amount">Total</th><th>Estado</th><th>Fichero bancario</th></tr></thead><tbody><tr v-for="row in history" :key="row.id" :data-remittance-id="row.id"><td>{{ row.id }}</td><td>{{ row.direction==='issued'?'Cobros · 19':'Pagos · 34' }}</td><td>{{ date(row.requested_date) }}</td><td>{{ row.count }}</td><td class="amount">{{ money(row.total) }}</td><td>{{ statuses[row.status] }}</td><td><div class="actions"><button class="button" :disabled="busy" @click="download(row)">{{ row.status==='prepared'?'Descargar XML':'Descargar copia histórica' }}</button><button v-if="row.status==='prepared'" class="button" :disabled="busy||!can('accounting_write')" @click="cancelling=row">Cancelar en el programa</button></div></td></tr><tr v-if="!history.length"><td colspan="7" class="empty-cell">{{ direction==='issued'?'Todavía no hay remesas de clientes.':'Todavía no hay remesas de proveedores.' }}</td></tr></tbody></table></div></section>
 <FormDialog v-if="review" title="Revisar remesa bancaria" :busy="busy" @close="review=null"><p>{{ review.direction==='issued'?'Cobros por domiciliación SEPA CORE':'Pagos por transferencia SEPA' }} · A partir de {{ date(review.requested_date) }}</p><p>Titular: <strong>{{ review.company.name }}</strong></p><p>Cuenta de la empresa: <strong>{{ review.bank.iban }}</strong></p><p v-if="review.bank.bic">BIC: {{ review.bank.bic }}</p><p v-if="review.bank.initiator_id">Presentador: {{ review.bank.initiator_id }}</p><p v-if="review.direction==='issued'">Acreedor SEPA: {{ review.bank.creditor_id }}</p><p v-for="issue in review.issues" :key="issue" class="notice error-notice">{{ remittanceError({code:issue}) }}</p><div class="table-wrap"><table><thead><tr><th>Recibo / factura</th><th>Tercero e IBAN</th><th>Fecha bancaria</th><th v-if="review.direction==='issued'">Mandato</th><th class="amount">Importe</th></tr></thead><tbody><tr v-for="row in review.items" :key="row.receipt_id"><td>{{ row.receipt_id }} · {{ row.reference }}</td><td>{{ row.name }}<small class="trade-cell-note">{{ row.iban }}</small><p v-for="issue in row.issues" :key="issue" class="remittance-issue">{{ remittanceError({code:issue}) }}</p></td><td>{{ date(row.execution_date) }}<small class="trade-cell-note">Vencimiento: {{ date(row.due_date) }}</small></td><td v-if="review.direction==='issued'">{{ row.mandate?.reference }}<small class="trade-cell-note">{{ date(row.mandate?.signed_on) }} · {{ row.mandate?.sequence }}</small></td><td class="amount">{{ money(row.amount) }}</td></tr></tbody></table></div><p><strong>Total: {{ money(review.total) }} €</strong> · {{ review.items.length }} recibos</p><p class="notice">Se descargará un fichero XML para cargar en la banca electrónica. Se respetan los vencimientos futuros. Los vencidos se presentan a partir de la fecha indicada. Los recibos quedan reservados en esta remesa hasta cancelarla.</p><div class="actions"><button class="button primary" :disabled="busy||!review.ready||!can('accounting_write')" @click="generate">Generar y descargar XML</button><button class="button" :disabled="busy" @click="review=null">Volver</button></div></FormDialog>
 <FormDialog v-if="cancelling" :title="'Cancelar remesa '+cancelling.id+' en el programa'" :busy="busy" @close="cancelling=null"><p>{{ cancelling.count }} recibos · {{ money(cancelling.total) }} € · {{ date(cancelling.requested_date) }}</p><p class="notice">Los recibos volverán a estar disponibles para editar o remesar. Si ya has entregado este fichero al banco, esta acción no retira la orden bancaria: gestiona primero su cancelación con el banco.</p><div class="actions"><button class="button primary" :disabled="busy" @click="cancel">Cancelar remesa en el programa</button><button class="button" :disabled="busy" @click="cancelling=null">Volver</button></div></FormDialog>
</template>
<style scoped>
.remittance-settings{padding:18px}.remittance-settings fieldset{border:0;margin:0;padding:0;min-width:0}.remittance-settings input[type=checkbox]{width:18px;height:18px}.remittance-history{margin-top:22px;padding:18px}.remittance-issue{color:#a13925;font-size:.86rem;margin:3px 0}.remittance-settings .actions{margin-top:18px}.remittance-settings .filters{margin-bottom:16px}
</style>
